# Terraform Module: S3 + RDS + IAM

I'll provide a complete, modular Terraform implementation supporting dev/prod via `.tfvars` files.

## Directory Structure

```
.
├── main.tf                    # Root module calls
├── variables.tf               # Root input variables
├── outputs.tf                 # Root outputs
├── dev.tfvars                 # Dev environment config
├── prod.tfvars                # Prod environment config
├── .gitignore                 # Excludes secrets
├── modules/
│   ├── s3/
│   │   ├── main.tf
│   │   ├── variables.tf
│   │   └── outputs.tf
│   ├── rds/
│   │   ├── main.tf
│   │   ├── variables.tf
│   │   └── outputs.tf
│   └── iam/
│       ├── main.tf
│       ├── variables.tf
│       └── outputs.tf
└── .sops.yaml                 # SOPS config for secrets
```

## Root Module

**main.tf:**
```hcl
terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
  # Uncomment for remote state:
  # backend "s3" {
  #   bucket         = "my-terraform-state"
  #   key            = "app/terraform.tfstate"
  #   region         = "us-east-1"
  #   encrypt        = true
  #   dynamodb_table = "terraform-lock"
  # }
}

provider "aws" {
  region = var.aws_region
  default_tags {
    tags = {
      Environment = var.environment
      Project     = var.project_name
      ManagedBy   = "Terraform"
    }
  }
}

module "s3" {
  source = "./modules/s3"

  bucket_name              = "${var.project_name}-assets-${var.environment}"
  environment              = var.environment
  enable_replication       = var.enable_s3_replication
  replication_region       = var.s3_replication_region
  kms_key_id               = var.kms_key_id
}

module "rds" {
  source = "./modules/rds"

  identifier           = "${var.project_name}-db-${var.environment}"
  environment          = var.environment
  instance_class       = var.rds_instance_class
  allocated_storage    = var.rds_storage_gb
  multi_az             = var.rds_multi_az
  backup_retention_days = var.backup_retention_days
  db_password          = var.db_password
  db_username          = var.db_username
  kms_key_id           = var.kms_key_id
  vpc_security_group_ids = [aws_security_group.rds.id]
  db_subnet_group_name = aws_db_subnet_group.default.name
}

module "iam" {
  source = "./modules/iam"

  role_name              = "${var.project_name}-service-role-${var.environment}"
  environment            = var.environment
  s3_bucket_arn          = module.s3.bucket_arn
  rds_resource_arn       = module.rds.resource_arn
  kms_key_arn            = data.aws_kms_key.key.arn
}

# Minimal VPC setup (assumes pre-existing VPC in production)
resource "aws_security_group" "rds" {
  name_prefix = "${var.project_name}-rds-"
  description = "RDS security group for ${var.environment}"
  vpc_id      = var.vpc_id

  ingress {
    from_port       = 5432
    to_port         = 5432
    protocol        = "tcp"
    security_groups = [var.app_security_group_id]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "${var.project_name}-rds-sg"
  }
}

resource "aws_db_subnet_group" "default" {
  name_prefix = "${var.project_name}-"
  subnet_ids  = var.db_subnet_ids

  tags = {
    Name = "${var.project_name}-db-subnet-group"
  }
}

data "aws_kms_key" "key" {
  key_id = var.kms_key_id
}
```

**variables.tf:**
```hcl
variable "aws_region" {
  description = "AWS region"
  type        = string
  default     = "us-east-1"
}

variable "environment" {
  description = "Environment name (dev or prod)"
  type        = string
  validation {
    condition     = contains(["dev", "prod"], var.environment)
    error_message = "Environment must be 'dev' or 'prod'."
  }
}

variable "project_name" {
  description = "Project name for resource naming"
  type        = string
  default     = "myapp"
}

variable "vpc_id" {
  description = "VPC ID for RDS and security groups"
  type        = string
}

variable "db_subnet_ids" {
  description = "Subnet IDs for RDS subnet group"
  type        = list(string)
}

variable "app_security_group_id" {
  description = "Security group ID of application (for RDS ingress)"
  type        = string
}

variable "rds_instance_class" {
  description = "RDS instance class"
  type        = string
  # Overridden per environment via tfvars
}

variable "rds_storage_gb" {
  description = "RDS allocated storage in GB"
  type        = number
  default     = 20
}

variable "rds_multi_az" {
  description = "Enable Multi-AZ deployment"
  type        = bool
  default     = false
}

variable "backup_retention_days" {
  description = "RDS backup retention period (days)"
  type        = number
  default     = 7
}

variable "db_username" {
  description = "RDS master username"
  type        = string
  default     = "postgres"
  sensitive   = true
}

variable "db_password" {
  description = "RDS master password (use -var or secrets.tfvars)"
  type        = string
  sensitive   = true
}

variable "kms_key_id" {
  description = "KMS key ID for encryption (alias/aws/s3 or custom ARN)"
  type        = string
  default     = "alias/aws/s3"
}

variable "enable_s3_replication" {
  description = "Enable S3 cross-region replication"
  type        = bool
  default     = false
}

variable "s3_replication_region" {
  description = "Target region for S3 replication"
  type        = string
  default     = "us-west-2"
}
```

**outputs.tf:**
```hcl
output "s3_bucket_name" {
  description = "S3 bucket name"
  value       = module.s3.bucket_name
}

output "s3_bucket_arn" {
  description = "S3 bucket ARN"
  value       = module.s3.bucket_arn
}

output "rds_endpoint" {
  description = "RDS instance endpoint"
  value       = module.rds.endpoint
  sensitive   = false
}

output "rds_port" {
  description = "RDS instance port"
  value       = module.rds.port
}

output "iam_role_arn" {
  description = "Service role ARN"
  value       = module.iam.role_arn
}

output "iam_role_name" {
  description = "Service role name"
  value       = module.iam.role_name
}
```

---

## S3 Module

**modules/s3/main.tf:**
```hcl
resource "aws_s3_bucket" "app_assets" {
  bucket_prefix = var.bucket_name

  tags = {
    Name = var.bucket_name
  }
}

# Block all public access
resource "aws_s3_bucket_public_access_block" "app_assets" {
  bucket = aws_s3_bucket.app_assets.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Enable versioning
resource "aws_s3_bucket_versioning" "app_assets" {
  bucket = aws_s3_bucket.app_assets.id

  versioning_configuration {
    status = "Enabled"
  }
}

# Server-side encryption
resource "aws_s3_bucket_server_side_encryption_configuration" "app_assets" {
  bucket = aws_s3_bucket.app_assets.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = var.kms_key_id != "alias/aws/s3" ? "aws:kms" : "AES256"
      kms_master_key_id = var.kms_key_id != "alias/aws/s3" ? var.kms_key_id : null
    }
    bucket_key_enabled = true
  }
}

# Cross-region replication (prod only)
resource "aws_s3_bucket_replication_configuration" "app_assets" {
  count = var.enable_replication ? 1 : 0

  bucket       = aws_s3_bucket.app_assets.id
  role         = aws_iam_role.replication[0].arn
  depends_on   = [aws_s3_bucket_versioning.app_assets]

  rule {
    id     = "ReplicateAll"
    status = "Enabled"

    destination {
      bucket       = aws_s3_bucket.replica[0].arn
      storage_class = "STANDARD_IA"

      replication_time {
        status = "Enabled"
        time {
          minutes = 15
        }
      }

      metrics {
        status = "Enabled"
        event_threshold {
          minutes = 15
        }
      }
    }
  }
}

resource "aws_s3_bucket" "replica" {
  count         = var.enable_replication ? 1 : 0
  bucket_prefix = "${var.bucket_name}-replica-"
  provider      = aws.replica
}

resource "aws_s3_bucket_versioning" "replica" {
  count    = var.enable_replication ? 1 : 0
  bucket   = aws_s3_bucket.replica[0].id
  provider = aws.replica

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_iam_role" "replication" {
  count = var.enable_replication ? 1 : 0

  name_prefix = "s3-replication-"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = {
        Service = "s3.amazonaws.com"
      }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_policy" "replication" {
  count = var.enable_replication ? 1 : 0

  name_prefix = "s3-replication-"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "s3:GetReplicationConfiguration",
          "s3:ListBucket",
        ]
        Resource = aws_s3_bucket.app_assets.arn
      },
      {
        Effect = "Allow"
        Action = [
          "s3:GetObjectVersionForReplication",
          "s3:GetObjectVersionAcl",
        ]
        Resource = "${aws_s3_bucket.app_assets.arn}/*"
      },
      {
        Effect = "Allow"
        Action = [
          "s3:ReplicateObject",
          "s3:ReplicateDelete",
        ]
        Resource = "${aws_s3_bucket.replica[0].arn}/*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "replication" {
  count      = var.enable_replication ? 1 : 0
  role       = aws_iam_role.replication[0].name
  policy_arn = aws_iam_policy.replication[0].arn
}
```

**modules/s3/variables.tf:**
```hcl
variable "bucket_name" {
  description = "S3 bucket name (prefix)"
  type        = string
}

variable "environment" {
  description = "Environment (dev or prod)"
  type        = string
}

variable "enable_replication" {
  description = "Enable cross-region replication"
  type        = bool
  default     = false
}

variable "replication_region" {
  description = "Target region for replication"
  type        = string
  default     = "us-west-2"
}

variable "kms_key_id" {
  description = "KMS key ID for encryption"
  type        = string
  default     = "alias/aws/s3"
}
```

**modules/s3/outputs.tf:**
```hcl
output "bucket_name" {
  value = aws_s3_bucket.app_assets.id
}

output "bucket_arn" {
  value = aws_s3_bucket.app_assets.arn
}

output "bucket_region" {
  value = aws_s3_bucket.app_assets.region
}
```

