## RDS Module

**modules/rds/main.tf:**
```hcl
resource "aws_db_instance" "postgres" {
  identifier            = var.identifier
  engine                = "postgres"
  engine_version        = "15.3"
  instance_class        = var.instance_class
  allocated_storage     = var.allocated_storage
  storage_encrypted     = true
  kms_key_id            = var.kms_key_id

  db_name  = "appdb"
  username = var.db_username
  password = var.db_password

  multi_az                    = var.multi_az
  publicly_accessible         = false
  skip_final_snapshot         = var.environment == "dev" ? true : false
  final_snapshot_identifier   = var.environment == "prod" ? "${var.identifier}-final-snapshot" : null

  backup_retention_period = var.backup_retention_days
  backup_window           = "03:00-04:00"
  maintenance_window      = "mon:04:00-mon:05:00"

  db_subnet_group_name   = var.db_subnet_group_name
  vpc_security_group_ids = var.vpc_security_group_ids

  deletion_protection = var.environment == "prod" ? true : false
  copy_tags_to_snapshot = true
  storage_type         = "gp3"
  iops                 = var.iops
  storage_throughput   = var.storage_throughput

  # Enable enhanced monitoring
  monitoring_interval    = 60
  monitoring_role_arn    = aws_iam_role.rds_monitoring.arn
  enable_cloudwatch_logs_exports = ["postgresql"]

  # Enable automated minor version upgrades
  auto_minor_version_upgrade = true

  # PostgreSQL parameter group for performance tuning
  parameter_group_name = aws_db_parameter_group.postgres.name

  tags = {
    Name = var.identifier
  }

  depends_on = [aws_db_parameter_group.postgres]
}

resource "aws_db_parameter_group" "postgres" {
  family      = "postgres15"
  name_prefix = "${var.identifier}-"

  parameter {
    name  = "log_statement"
    value = "all"
  }

  tags = {
    Name = "${var.identifier}-pg"
  }
}

resource "aws_iam_role" "rds_monitoring" {
  name_prefix = "rds-monitoring-"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = {
        Service = "monitoring.rds.amazonaws.com"
      }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "rds_monitoring" {
  role       = aws_iam_role.rds_monitoring.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonRDSEnhancedMonitoringRole"
}

resource "aws_db_instance_automated_backups_replication" "postgres" {
  count = var.enable_backup_replication ? 1 : 0

  source_db_instance_arn = aws_db_instance.postgres.arn
  retention_period       = var.backup_retention_days
}
```

**modules/rds/variables.tf:**
