## IAM Module

**modules/iam/main.tf:**
```hcl
resource "aws_iam_role" "service" {
  name = var.role_name

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          AWS = var.principal_arns
        }
        Action = "sts:AssumeRole"
        Condition = var.environment == "prod" ? {
          StringEquals = {
            "sts:ExternalId" = var.external_id
          }
        } : {}
      },
      # OIDC trust for IRSA (if using EKS)
      var.oidc_provider_arn != "" ? {
        Effect = "Allow"
        Principal = {
          Federated = var.oidc_provider_arn
        }
        Action = "sts:AssumeRoleWithWebIdentity"
        Condition = {
          StringEquals = {
            "${replace(var.oidc_provider_arn, "/^.*provider//", "")}:sub" = "system:serviceaccount:${var.namespace}:${var.service_account}"
          }
        }
      } : null
    ]
  })

  tags = {
    Name = var.role_name
  }
}

# S3 permissions (least privilege)
resource "aws_iam_policy" "s3_access" {
  name_prefix = "${var.role_name}-s3-"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:DeleteObject",
        ]
        Resource = "${var.s3_bucket_arn}/*"
      },
      {
        Effect = "Allow"
        Action = [
          "s3:ListBucket",
          "s3:GetBucketVersioning",
        ]
        Resource = var.s3_bucket_arn
      },
      {
        Effect = "Allow"
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey",
          "kms:DescribeKey",
        ]
        Resource = "*"
        Condition = {
          StringEquals = {
            "kms:ViaService" = "s3.*.amazonaws.com"
          }
        }
      }
    ]
  })
}

# RDS permissions (least privilege)
resource "aws_iam_policy" "rds_access" {
  name_prefix = "${var.role_name}-rds-"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "rds-db:connect",
        ]
        Resource = "${var.rds_resource_arn}/*"
      },
      {
        Effect = "Allow"
        Action = [
          "rds:DescribeDBInstances",
        ]
        Resource = var.rds_resource_arn
      }
    ]
  })
}

# Attach policies
resource "aws_iam_role_policy_attachment" "s3" {
  role       = aws_iam_role.service.name
  policy_arn = aws_iam_policy.s3_access.arn
}

resource "aws_iam_role_policy_attachment" "rds" {
  role       = aws_iam_role.service.name
  policy_arn = aws_iam_policy.rds_access.arn
}

# Inline policy for KMS (if needed)
resource "aws_iam_role_policy" "kms" {
  count = var.kms_key_arn != "" ? 1 : 0
  name  = "${var.role_name}-kms"
  role  = aws_iam_role.service.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Action = [
        "kms:Decrypt",
        "kms:DescribeKey",
      ]
      Resource = var.kms_key_arn
    }]
  })
}
```

**modules/iam/variables.tf:**
```hcl
variable "role_name" {
  description = "IAM role name"
  type        = string
}

variable "environment" {
  description = "Environment (dev or prod)"
  type        = string
}

variable "s3_bucket_arn" {
  description = "S3 bucket ARN"
  type        = string
}

variable "rds_resource_arn" {
  description = "RDS resource ARN"
  type        = string
}

variable "kms_key_arn" {
  description = "KMS key ARN"
  type        = string
  default     = ""
}

variable "principal_arns" {
  description = "ARNs that can assume this role"
  type        = list(string)
  default     = []
}

variable "external_id" {
  description = "External ID for assume role (prod only)"
  type        = string
  sensitive   = true
  default     = ""
}

variable "oidc_provider_arn" {
  description = "OIDC provider ARN (for EKS IRSA)"
  type        = string
  default     = ""
}

variable "namespace" {
  description = "Kubernetes namespace"
  type        = string
  default     = "default"
}

variable "service_account" {
  description = "Kubernetes service account name"
  type        = string
  default     = ""
}
```

**modules/iam/outputs.tf:**
```hcl
